with src as (select * from shipments where status in ('IN_TRANSIT', 'LOST') and order_id is not null), status_group_summary as (select case when status in ('RETURNED', 'DELIVERED') then 'core' else 'other' end status_group, max(delivered_date) latest_delivered_date, min(shipped_date) first_shipped_date from src group by case when status in ('RETURNED', 'DELIVERED') then 'core' else 'other' end) select * from status_group_summary order by 2, 3 desc
